Translate("ptBR", "terenthis", {
	title = "Terenthis",
	subtitle = "Vigia dos Bosqueneros",
	found = "Auberdine, perto do posto das Sentinelas",
	hint = [=[Fale com o elfo noturno de Auberdine que caça os sinais da corrupção.]=],
	allegiance = "Auberdine · Elfos noturnos",
	sections = {
		{
			title = "Resumo",
			text = [=[Terenthis é um {link:night-elves}elfo noturno{/link} de {link:auberdine}Auberdine{/link} que jurou encontrar a corrupção em sua origem. Alguns de seus parentes foram salvos de um {link:furbolgs}pelurso{/link} corrompido em {link:teldrassil}Teldrassil{/link}. Desde aquele dia, ele jurou que nenhum outro de seu povo sofreria do mesmo modo, e vigia de perto os pelursos da {link:darkshore}Costa Negra{/link}.]=],
		},
		{
			title = "Importância",
			text = [=[Terenthis foi um dos primeiros a mostrar o quanto o perigo se aproximara. Seus batedores encontraram os acampamentos {link:blackwood-furbolgs}Bosqueneros{/link} corrompidos à vista de {link:auberdine}Auberdine{/link}. Ele é também amigo dos que vivem sozinhos nos ermos, e um amigo em apuros o encontra pronto.]=],
		},
		{
			title = "Feitos",
			text = [=[• Enviou batedores para encontrar um acampamento de pelursos corrompidos, e combatentes para rarear suas fileiras.
• Confeccionou um manto encantado de peles de espreitador da lua que permitia a quem o vestisse andar sem ser visto pelas feras da {link:darkshore}Costa Negra{/link}.
• Trouxe {link:volcor}Volcor{/link} para casa do {link:blackwood-den}Antro dos Bosqueneros{/link}.
• Envia suas descobertas ao ancião, {link:thundris-windweaver}Thundris Windweaver{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Quão Grande É a Ameaça?",
			hint = [=[Encontre um acampamento de pelursos corrompidos perto de Auberdine.]=],
			text = [=[O acampamento ao sul de {link:auberdine}Auberdine{/link} era pior do que Terenthis temera. Os {link:blackwood-furbolgs}Bosqueneros{/link} estavam corrompidos, e estavam perto. Ele disse a Auberdine que se preparasse para o que estava por vir. Disse também aos que tinham lutado ali que não se lamentassem. Tinham diminuído a ameaça, ainda que o musgo vil continuasse a envenenar a terra.]=],
		},
		{
			title = "Um Mestre Perdido",
			hint = "Atenda ao chamado da fera que veio sozinha a Auberdine.",
			text = [=[{link:grimclaw}Grimclaw{/link} chegou a {link:auberdine}Auberdine{/link} sem seu mestre. Terenthis entendeu de imediato. {link:volcor}Volcor{/link} estava ferido, em algum lugar ao sul, entre os pelursos. Ele costurou um manto que esconderia seu portador das feras, e avisou que sua magia falharia se quem o vestisse fizesse mais do que falar.]=],
		},
	},
	mentions = {
		{ text = "Um Mestre Perdido" },
		{ text = "Fuga pela Força" },
		{ text = "Fuga pela Furtividade" },
		{ text = "{link:thundris-windweaver}Thundris Windweaver{/link}" },
		{
			text = [=[Jornada ao {link:ashenvale}Vale Gris{/link}, um chamado da Sentinela Selarin]=],
		},
	},
	bonds = {
