		{ id = "grimclaw", name = "Grimclaw", note = "o companheiro de Volcor" },
		{ id = "thundris-windweaver", name = "Thundris Windweaver", note = "o ancião a quem ele se reporta" },
		{ id = "blackwood-furbolgs", name = "Pelursos Bosqueneros", note = "a corrupção que ele vigia" },
	},
})

Translate("ptBR", "onu", {
	title = "Onu",
	subtitle = "Anciente do Saber",
	found = "O Bosque dos Ancientes, no sul da Costa Negra",
	hint = [=[Procure o Anciente do Saber no bosque perto das montanhas do sul.]=],
	allegiance = "Os Ancientes · Bosque dos Ancientes",
	sections = {
		{
			title = "Resumo",
			text = [=[Onu é um Anciente do Saber, um dos grandes espíritos da floresta, e guarda o {link:grove-of-the-ancients}Bosque dos Ancientes{/link} no sul da {link:darkshore}Costa Negra{/link}. Fala devagar e com longas pausas, e não se apressa. Sabe que todas as coisas acontecem em seu devido tempo.]=],
		},
		{
			title = "Importância",
			text = [=[Onu é a memória da {link:darkshore}Costa Negra{/link}. Sabe o que os cultistas do {link:twilight-s-hammer}Martelo do Crepúsculo{/link} adoram, e sabe onde caiu um de seus antigos senhores. Os druidas e estudiosos de {link:auberdine}Auberdine{/link} levam a ele suas perguntas mais graves, e o Arquidruida {link:fandral-staghelm}Fandral Staghelm{/link} lhe envia mensagens de {link:darnassus}Darnassus{/link}.]=],
		},
		{
			title = "Feitos",
			text = [=[• Enviou vigias ao {link:the-master-s-glaive}Glaive do Mestre{/link} e soube que o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} estava lá.
• Estudou uma página arrancada do tomo do culto e sentiu nela a magia dos antigos.
• Reuniu relíquias de {link:ruins-of-mathystra}Mathistra{/link} para aprender como o culto usa a magia élfica.
• Fala de {link:malfurion-stormrage}Shan'do Stormrage{/link} como alguém que compreendia a paciência da floresta.]=],
		},
	},
	chapters = {
		{
			title = "O Glaive do Mestre",
			hint = "Vá ao Glaive do Mestre a pedido do Anciente.",
			text = [=[Onu achou estranho que os nagas tivessem vindo à {link:darkshore}Costa Negra{/link}. Achou mais estranho ainda que o {link:twilight-s-hammer}Martelo do Crepúsculo{/link} tivesse vindo. Quando seus temores se confirmaram, falou do antigo senhor empalado no Glaive. Esse senhor está morto. Seu poder, talvez, não esteja.]=],
		},
		{
			title = "Páginas dos Antigos",
			hint = "Traga ao Anciente o que foi tomado do acampamento do culto.",
			text = [=[Os rabiscos arrancados do Tomo do Crepúsculo continham uma magia caótica, e por baixo dela havia a escrita dos elfos. O culto estava usando antiga feitiçaria élfica para trazer seus antigos senhores de volta ao mundo. Onu pôs-se a descobrir como, antes que seus inimigos pudessem terminar o que tinham começado.]=],
		},
		{
			title = "A Escadaria sob Mathistra",
			hint = "Traga ao Anciente o que restou do guardião de Mathistra.",
			text = [=[Quando o globo de água turva foi posto diante dele, Onu mostrou algo próximo da surpresa. Havia uma escadaria sob {link:ruins-of-mathystra}Mathistra{/link}, e um guardião a vigiava. Disse apenas que precisava falar com os outros Ancientes, e que era bom que a escadaria tivesse sido encontrada antes que os nagas ou o culto a encontrassem.]=],
		},
	},
	mentions = {
		{
			text = [=[Onu, convocado por {link:barithras-moonshade}Barithras Moonshade{/link}]=],
		},
		{ text = "O {link:twilight-base-camp}Acampamento do Crepúsculo{/link}" },
		{
			text = [=[{link:grove-of-the-ancients}Bosque dos Ancientes{/link}, uma mensagem de {link:fandral-staghelm}Fandral Staghelm{/link}]=],
		},
	},
	bonds = {
		{ id = "arbal", name = "Arbal", note = "está com ele no bosque" },
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "dá ouvidos a seus avisos" },
		{ id = "fandral-staghelm", name = "Fandral Staghelm", note = "envia-lhe notícias" },
		{ id = "baron-marinous", name = "Barão Marinous", note = "o guardião de Mathistra" },
	},
})

