			text = [=[As {link:sentinels}Sentinelas{/link} não a caçaram de bom grado. Sua queda é mais um sinal de que algo deu errado com as criaturas da {link:darkshore}Costa Negra{/link}, dos ursos da floresta às aves das colinas.]=],
		},
	},
	mentions = {
		{ text = "PROCURADO: Jai'vhanel" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Sentinela Glynda Nal'Shea", note = "pôs o preço em sua cabeça" },
	},
})

Translate("ptBR", "lord-sinslayer", {
	title = "Lorde Sinslayer",
	subtitle = "Naga das Quedas de Fontescarpa",
	found = "A caverna atrás das Quedas de Fontescarpa",
	hint = [=[Enfrente o lorde naga que espreita na caverna atrás das Quedas de Fontescarpa.]=],
	allegiance = "Nagas",
	aliases = { "Sinslayer" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Lorde Sinslayer lidera os {link:naga}nagas{/link} que tomaram a caverna atrás das {link:cliffspring-falls}Quedas de Fontescarpa{/link}. Os Ancientes sentiram o mal naquela caverna antes que qualquer elfo o tivesse visto. As quedas dão à {link:darkshore}Costa Negra{/link} boa parte de sua água potável, e o veneno que agora corre delas adoeceu os cervos por toda a terra.]=],
		},
		{ title = "Sem Registro", text = "Pouco se sabe de Sinslayer além de seu nome e seu covil." },
		{
			title = "Importância",
			text = [=[A caverna de Sinslayer fica mais perto de {link:auberdine}Auberdine{/link} do que {link:ruins-of-mathystra}Mathistra{/link}. Sua presença mostra que os nagas já não se contentam com as velhas ruínas do nordeste.]=],
		},
	},
	bonds = {
		{ id = "barithras-moonshade", name = "Barithras Moonshade", note = "foi avisado sobre sua caverna" },
	},
})

Translate("ptBR", "murkdeep", {
	title = "Murkdeep",
	subtitle = "Terror dos Greymist",
	found = "Um acampamento murloc na costa ao sul de Auberdine",
	hint = "Enfrente o murloc que guarda as cabanas na costa do sul.",
	allegiance = "Murlocs Greymist",
	sections = {
		{
			title = "Resumo",
			text = [=[Murkdeep é um {link:murlocs}murloc{/link} da tribo Greymist que guarda um acampamento de cabanas na costa ao sul de {link:auberdine}Auberdine{/link}. Matou pelo menos uma Sentinela. Também se acredita que tenha afundado dois navios de carga ao largo da costa. O conselho da vila pôs um preço em sua cabeça, e o povo da cidade diz que dormirá mais tranquilo quando for pago.]=],
		},
		{
			title = "Importância",
			text = [=[Murkdeep é a razão pela qual os pescadores de {link:auberdine}Auberdine{/link} mantêm seus barcos em terra, e a razão pela qual a carga vinda do mar chega atrasada ou não chega.]=],
		},
	},
	mentions = {
		{ text = "PROCURADO: Murkdeep!" },
	},
	bonds = {
		{ id = "sentinel-glynda-nal-shea", name = "Sentinela Glynda Nal'Shea", note = "paga a recompensa" },
	},
})

Translate("ptBR", "kerlonian-evershade", {
	title = "Kerlonian Evershade",
	subtitle = "Druida da Garra",
	found = "Perto do Bosque dos Ancientes",
	hint = [=[Encontre o druida sonolento que perdeu suas coisas perto do bosque do sul.]=],
