	aliases = { "Kerlonian" },
	sections = {
		{
			title = "Resumo",
			text = [=[Kerlonian Evershade é um Druida da Garra que despertou há pouco do {link:emerald-dream}Sonho Esmeralda{/link}. Desde então vive sonolento. Partiu para o {link:maestra-s-post}Entreposto de Maestra{/link} para encontrar {link:liladris-moonriver}Liladris Moonriver{/link}, parou para um breve cochilo e perdeu seus pertences. Uma trompa em seu baú o acordará se ele cochilar de novo.]=],
