Translate("ptBR", "cult-of-the-dark-strand", {
	title = "Cult of the Dark Strand",
	aliases = { "Dark Strand" },
	sections = {
		{
			title = "Resumo",
			text = [=[O Cult of the Dark Strand é um grupo de bruxos que tomou a {link:tower-of-althalaxx}Torre de Althalaxx{/link} na {link:darkshore}Costa Negra{/link}. Não tinha nenhum nome conhecido pelas {link:sentinels}Sentinelas{/link} até que {link:balthule-shadowstrike}Balthule Shadowstrike{/link} juntou um a partir de restos de seu pergaminho. Seus fanáticos e invocadores do vazio servem a {link:athrikus-narassin}Athrikus Narassin{/link}, o antigo lorde Bem-nascido da torre.]=],
		},
		{
			title = "Seu Poder",
			text = [=[O culto tira sua força de gemas de alma. {link:athrikus-narassin}Athrikus{/link} mantinha nelas as almas de Bem-nascidos aprisionadas, e as escondeu nas terras dos sátiros no norte do {link:ashenvale}Vale Gris{/link}, na {link:night-run}Trilha da Noite{/link} e em {link:satyrnaar}Satyrnaar{/link}. O culto também atua em {link:the-ruins-of-ordil-aran}Ordil'Aran{/link}, no Vale Gris. Tem negócios com o bruxo {link:orcs}orc{/link} {link:ilkrud-magthrull}Ilkrud Magthrull{/link}, do {link:fire-scar-shrine}Santuário Cicatriz de Fogo{/link}, que mantinha anotações sobre seus planos. {link:delgren-the-purifier}Delgren, o Purificador{/link}, fez do fim do culto a sua tarefa.]=],
		},
	},
})

Translate("ptBR", "blackwood-furbolgs", {
	title = "Pelursos Bosqueneros",
	aliases = { "Bosqueneros", "tribo Bosquenera" },
	sections = {
		{
			title = "Resumo",
			text = [=[Os Bosqueneros são uma tribo de {link:furbolgs}pelursos{/link} da {link:darkshore}Costa Negra{/link}. Eram amigos dos elfos noturnos, e os elfos ainda se lembram deles assim. Agora estão corrompidos. Vivem em acampamentos ao longo do {link:cliffspring-river}Rio Fontescarpa{/link}, no norte e no sul, e atacam qualquer elfo que se aproxime.]=],
		},
		{
			title = "A Corrupção",
			text = [=[Os elfos de {link:auberdine}Auberdine{/link} atribuíram parte da loucura dos Bosqueneros aos sátiros. Um {link:satyrs}sátiro{/link} corruptor os domina por meio de um talismã. Quando os pelursos comeram comida misturada com água do poço lunar, ficaram purificados por pouco tempo. O ancião de Auberdine espera que um dia possam ser libertados de vez. Mas o veneno mais profundo corre na terra e na água, e vem da {link:felwood}Selva Maleva{/link}.]=],
		},
	},
})
